export const wordBanks={a:['cat','map','cap','bag'],i:['pin','tin','bin','lid'],o:['dog','log','pot','top'],e:['pen','hen','bed','net'],u:['sun','cup','bus','bug'],cvcc:['lamp','tent','nest','hand'],ccvc:['flag','frog','crab','drum'],digraph:['ship','fish','shop','chin'],longer:['shell','chick','chest','brush']};
export const groupNames={a:'Short a',i:'Short i',o:'Short o',e:'Short e',u:'Short u',cvcc:'Four letters: final blends',ccvc:'Four letters: initial blends',digraph:'Two letters, one sound',longer:'Five letters: sound teams'};
export function segmentWord(word){return word.match(/igh|ear|air|ure|sh|ch|th|ng|ck|ll|ss|ff|ai|ee|oa|oo|ar|or|ur|ow|oi|./g)||[];}
const modes=['listen','build','picture'];
export function makeTask(group,type,word,offset=0){const bank=wordBanks[group],alternatives=bank.filter(w=>w!==word);const options=[word,...alternatives];return {type,word,group,skill:type+':'+group,taskId:group+':'+type+':'+word,graphemes:segmentWord(word),options,correct:0,hidden:true};}
export function rescueTasks(group,offset=0){const bank=wordBanks[group];return modes.map((type,i)=>makeTask(group,type,bank[(i+offset)%bank.length],offset));}
export function skillSummary(profile){const attempts=profile.attempts.filter(a=>a.skill);const keys=[...new Set(attempts.map(a=>a.skill))];return keys.map(skill=>{const items=attempts.filter(a=>a.skill===skill),success=items.filter(a=>a.correct),ind=success.filter(a=>!a.supported),sessions=new Set(ind.map(a=>a.session));const latest=items.at(-1);return {skill,group:skill.split(':')[1],mode:skill.split(':')[0],correct:success.length,independent:ind.length,supported:success.filter(a=>a.supported).length,status:sessions.size>=2?'revisited':ind.length?'independent':success.length?'helped':'practice',priority:(latest?.supported||!latest?.correct?4:0)+(sessions.size<2?2:0)};});}
export function reviewTasks(profile,seed=0){const summaries=skillSummary(profile);const chosen=profile.focus&&wordBanks[profile.focus]?profile.focus:null;const available=[...new Set(summaries.map(s=>s.group))];const group=chosen||summaries.slice().sort((a,b)=>b.priority-a.priority)[0]?.group||available[0]||'a';return modes.map((type,i)=>{const seen=profile.attempts.filter(a=>a.skill===type+':'+group&&a.correct&&!a.supported).map(a=>a.word);const bank=wordBanks[group];const candidates=bank.filter(w=>!seen.includes(w));return makeTask(group,type,(candidates.length?candidates:bank)[(seed+i)%(candidates.length||bank.length)]);});}
export function mismatchedPositions(task,answer){if(!['build','change'].includes(task.type))return [];return task.graphemes.flatMap((g,i)=>answer[i]===g?[]:[i]);}
export function distractorTiles(task,difficulty='standard'){const extras=difficulty==='guided'?0:difficulty==='challenge'?3:1;const neighbours=wordBanks[task.group]||[task.word];const pool=[...new Set([...task.graphemes,...neighbours.flatMap(segmentWord)])];return [...new Set([...task.graphemes,...pool.filter(x=>!task.graphemes.includes(x)).slice(0,extras)])];}

